// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1_000_000 ether);

        uint256 startingContractBalance = address(c).balance;
        uint256 startingUserBalance = c.getBalance(actor);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 endingContractBalance = address(c).balance;
        uint256 endingUserBalance = c.getBalance(actor);

        assertTrue(
            endingContractBalance - startingContractBalance == endingUserBalance - startingUserBalance
        );
    }
}
